import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
FIX = os.path.join(HERE, "fixtures") + os.sep
REPO = os.path.dirname(os.path.dirname(HERE))
sys.path.insert(0, HERE)
import sys, re
from shots import run, BASE, OUT

results = []
def check(name, cond, detail=""):
    results.append((name, bool(cond), str(detail)))
def data(page, expr):
    return page.evaluate("(() => { const s = JSON.parse(localStorage.getItem('cod.data')).state; const db = s.db; const day = s.day; return " + expr + "; })()")
def as_role(page, role):
    page.get_by_role("button", name="Account menu").click()
    page.get_by_role("menuitem", name=role).click()
    page.wait_for_timeout(350)
def go(page, path, sel="main"):
    page.goto(BASE + path); page.wait_for_selector(sel); page.wait_for_timeout(250)

def steps(page, ctx):
    page.goto(BASE + "/"); page.wait_for_url("**/sign-in")
    page.fill("#username", "demo"); page.fill("#password", "demo"); page.click("button[type=submit]")
    page.wait_for_url("**/who"); page.get_by_role("button", name="Managing director").click(); page.wait_for_url("**/dashboard")
    main = page.locator("main")
    dlg = lambda: page.locator("dialog[open]").last

    # ── Plant overview: list by site
    go(page, "/plant", "table")
    t = main.inner_text()
    check("Plant: overview counts own plant, hire and what is overdue", "24 items of our own plant and 8 on hire" in t and "2 hires waiting to be collected" in t, t[:200])
    c719 = page.locator("section", has=page.get_by_role("link", name="C719 St Finian's Church"))
    check("Plant: a block per site lists own plant and hired plant together", c719.locator("tr", has_text="MX1").count() == 1 and c719.locator("tr", has_text="Corrib Scaffolding").count() == 1 and page.locator("section", has_text="In the yard").count() >= 1)
    widths = page.evaluate("[...document.querySelectorAll('main table')].slice(0,4).map(t => Math.round(t.querySelectorAll('th')[2].getBoundingClientRect().left))")
    check("Plant: columns line up from one site block to the next", len(set(widths)) == 1, widths)
    n_all = page.locator("tbody tr").count()
    page.get_by_role("tab", name="Needs attention").click(); page.wait_for_timeout(250)
    n_att = page.locator("tbody tr").count()
    check("Plant: Needs attention narrows the list to overdue, due soon, repair and returns", 0 < n_att < n_all and "overdue" in main.inner_text() and "Return notified" in main.inner_text(), (n_all, n_att))
    page.screenshot(path=f"{OUT}/120-plant-attention.png")
    page.locator("tbody tr", has_text="HS2").click(); page.wait_for_timeout(300)
    d = dlg()
    check("Plant item: shows the overdue certificate with nothing on file", "Thorough examination" in d.inner_text() and "No certificate on file" in d.inner_text() and "Overdue by 23 days" in d.inner_text())
    d.locator("li", has_text="Thorough examination").get_by_role("button", name="Renew").click(); page.wait_for_timeout(250)
    r = dlg(); r.get_by_label("Choose a proof from this device").set_input_files(FIX + "cert.pdf"); page.wait_for_timeout(400)
    r.get_by_role("button", name="Save renewal").click(); page.wait_for_timeout(300)
    hs2 = data(page, "(() => { const r = db.plant.find(p=>p.assetRef==='HS2').renewals.find(r=>r.kind==='Thorough examination'); return [r.expires > day, r.proof.name, r.doc] })()")
    check("Plant item: renewing with a PDF attaches it and moves the date on", hs2 == [True, "cert.pdf", "cert.pdf"] and dlg().get_by_role("button", name="View proof").count() == 1, hs2)
    dlg().get_by_label("Where HS2 is").select_option("pr-C723"); page.wait_for_timeout(250)
    check("Plant item: moving it to another site is saved and logged", data(page, "[db.plant.find(p=>p.assetRef==='HS2').projectId, db.activity[0].what]") == ["pr-C723", "Moved plant"])
    dlg().get_by_role("button", name="Send for repair").click(); page.wait_for_timeout(250)
    check("Plant item: can be sent for repair and brought back", data(page, "db.plant.find(p=>p.assetRef==='HS2').status") == "Off for repair" and dlg().get_by_role("button", name="Back from repair").count() == 1)
    dlg().get_by_role("button", name="Back from repair").click(); page.wait_for_timeout(200)
    dlg().get_by_role("button", name="Close").click(); page.wait_for_timeout(200)
    go(page, "/plant?item=pl-GN1", "dialog[open]")
    check("Plant item: an hours-based service shows as overdue from the clock", "over" in dlg().inner_text() and "hrs on the clock" in dlg().inner_text(), dlg().inner_text()[:400])
    dlg().get_by_label("Service note").fill("Oil, filters and belt")
    dlg().get_by_role("button", name="Record service").click(); page.wait_for_timeout(250)
    gn = data(page, "(() => { const p = db.plant.find(p=>p.assetRef==='GN1'); return [p.service.lastServiced === day, p.service.lastMeter === p.service.meterNow, p.serviceHistory[0].note] })()")
    check("Plant item: recording a service resets the clock and adds to the history", gn == [True, True, "Oil, filters and belt"], gn)
    dlg().get_by_role("button", name="Close").click()
    go(page, "/plant", "table")
    page.locator("tr", has_text="12 m scissor lift").get_by_role("button", name="Mark collected").click(); page.wait_for_timeout(250)
    check("Plant: marking a hire collected stops it and takes it off the overview", page.locator("tr", has_text="12 m scissor lift").count() == 0 and data(page, "db.hiredPlant.find(h=>h.id==='hp-6').status") == "Collected")

    # ── Calendar, register, hired
    go(page, "/plant/calendar")
    check("Plant calendar: twelve weeks across, with own plant, hire and requests", "The next twelve weeks" in main.inner_text() and "hire" in main.inner_text() and "request" in main.inner_text())
    over = page.evaluate("(() => { const p = document.querySelector('main .min-w-\\\\[52rem\\\\]'); return p.scrollWidth - p.clientWidth })()")
    check("Plant calendar: no bar runs past the last week", over <= 1, over)
    page.screenshot(path=f"{OUT}/121-plant-calendar.png")
    go(page, "/plant/register", "table")
    check("Own plant: all 24 items, filterable by status", page.locator("tbody tr").count() == 24)
    page.get_by_role("tab", name="Off for repair").click(); page.wait_for_timeout(200)
    check("Own plant: one item is off for repair", page.locator("tbody tr").count() == 1 and "CP1" in main.inner_text())
    go(page, "/plant/hired", "table")
    check("Hired plant: weekly cost and a phone link for each hire company", "a week" in main.inner_text() and page.locator("tbody a[href^='tel:']").count() == page.locator("tbody tr").count())
    n_on = page.locator("tbody tr").count()
    page.locator("tbody tr").first.get_by_role("button", name="Notify return").click(); page.wait_for_timeout(250)
    check("Hired plant: notifying a return moves it to the next list", page.locator("tbody tr").count() == n_on - 1)

    # ── Fleet
    go(page, "/plant/vehicles", "table")
    check("Vehicles: 12 on the road with tax, test and insurance each flagged", page.locator("tbody tr").count() == 12 and "2 documents out of date" in main.inner_text() and "CVRT" in page.locator("thead").inner_text())
    page.locator("tbody tr", has_text="212-D-18834").click(); page.wait_for_timeout(300)
    docs0 = data(page, "db.fleetDocs.length")
    dlg().locator("li", has_text="CVRT").get_by_role("button", name="Renew").click(); page.wait_for_timeout(250)
    r = dlg(); r.get_by_label("Amount paid").fill("abc"); page.wait_for_timeout(100)
    check("Vehicle: a renewal cannot be saved with an amount that is not a number", r.get_by_role("button", name="Save renewal").is_disabled())
    r.get_by_label("Amount paid").fill("131.50"); r.get_by_role("button", name="Save renewal").click(); page.wait_for_timeout(300)
    v = data(page, "(() => { const v = db.vehicles.find(v=>v.reg==='212-D-18834'); return [v.compliance.test.expiryDate > day, v.compliance.test.amount, db.fleetDocs[0].category, db.fleetDocs[0].amount] })()")
    check("Vehicle: renewing the test updates it and files a document", v == [True, 131.5, "test", 131.5] and data(page, "db.fleetDocs.length") == docs0 + 1, v)
    dlg().get_by_role("button", name="Remove from fleet").click(); page.wait_for_timeout(150)
    dlg().get_by_label("Sold for").fill("lots"); dlg().get_by_role("button", name="Remove vehicle").click(); page.wait_for_timeout(200)
    check("Vehicle: removal needs a sale amount or NA", "or NA if it was not sold" in dlg().inner_text() and data(page, "db.vehicles.find(v=>v.reg==='212-D-18834').active") is True)
    dlg().get_by_label("Sold for").fill("NA"); dlg().get_by_role("button", name="Remove vehicle").click(); page.wait_for_timeout(300)
    check("Vehicle: removed with NA is recorded as not sold and leaves the list", page.locator("tbody tr").count() == 11 and data(page, "(() => { const v = db.vehicles.find(v=>v.reg==='212-D-18834'); return [v.active, v.sellPrice] })()") == [False, None])
    page.get_by_role("switch", name="Show vehicles removed from the fleet").click(); page.wait_for_timeout(200)
    check("Vehicles: removed vehicles are kept on their own list", page.locator("tbody tr").count() == 2 and "Not sold" in main.inner_text())
    page.get_by_role("switch", name="Show vehicles removed from the fleet").click()
    page.get_by_role("button", name="Add vehicle").click(); d = dlg()
    d.locator("button[type=submit]").click(); page.wait_for_timeout(150)
    check("Vehicles: registration and model are required", "Registration and model are needed" in d.inner_text())
    d.get_by_label("Registration").fill("231 g 4471"); d.get_by_label("Make and model").fill("Ford Transit"); d.locator("button[type=submit]").click(); page.wait_for_timeout(150)
    check("Vehicles: a registration already on the fleet is refused", "already on the fleet" in d.inner_text())
    d.get_by_label("Registration").fill("261 g 88"); d.locator("button[type=submit]").click(); page.wait_for_timeout(300)
    check("Vehicles: a new vehicle is added with its registration tidied", page.locator("tbody tr", has_text="261-G-88").count() == 1)
    go(page, "/plant/documents", "table")
    page.get_by_role("button", name="Add a document").click(); d = dlg()
    d.locator("button[type=submit]").click(); page.wait_for_timeout(150)
    check("Vehicle documents: an amount is required", "Enter the amount" in d.inner_text())
    d.get_by_label("Amount").fill("412.60"); d.get_by_label("Work done").fill("Full service, oil and filters"); d.get_by_label("Garage").fill("Oranmore Commercials"); d.get_by_label("Town and county").fill("Oranmore, Galway")
    d.get_by_label("Choose a proof from this device").set_input_files(FIX + "card.png"); page.wait_for_timeout(500)
    d.locator("button[type=submit]").click(); page.wait_for_timeout(300)
    check("Vehicle documents: a repair receipt is filed with its photo", page.locator("tbody tr").first.get_by_role("button", name="View proof").count() == 1 and "Full service, oil and filters" in page.locator("tbody tr").first.inner_text())
    page.get_by_role("tab", name="Insurance").click(); page.wait_for_timeout(200)
    check("Vehicle documents: filter by kind", page.locator("tbody tr").count() == 13 and all("Insurance" in t for t in page.locator("tbody tr td:nth-child(3)").all_inner_texts()))
    go(page, "/plant/repairs", "table")
    check("Repair spend: by vehicle with a fleet total, by garage and by quarter", page.locator("section", has_text="By vehicle").locator("tbody tr").count() == 14 and "Whole fleet" in main.inner_text() and page.locator("section", has_text="By garage").locator("tbody tr").count() >= 4 and re.search(r"20\d\d Q[1-4]", main.inner_text()) is not None)
    page.screenshot(path=f"{OUT}/122-repair-spend.png")
    as_role(page, "Site manager")
    go(page, "/plant", "table")
    check("Plant: a site manager sees only his own sites and has no buttons to change anything", main.get_by_role("link", name=re.compile("^C7")).count() == 2 and main.get_by_role("button", name="Notify return").count() + main.get_by_role("button", name="Mark collected").count() == 0, main.get_by_role("link", name=re.compile("^C7")).all_inner_texts())
    page.locator("tbody tr.rowlink").first.click(); page.wait_for_timeout(250)
    check("Plant: he can open an item but not move, renew or service it", dlg().locator("select").count() == 0 and dlg().get_by_role("button", name="Renew").count() == 0 and dlg().get_by_role("button", name="Record service").count() == 0)
    dlg().get_by_role("button", name="Close").click()
    as_role(page, "Managing director")

    # ── Files: the Files section (kept on 16 Nov, with To be sorted) and each project's Files tab
    go(page, "/files")
    check("Files: the Files section is in the bar", page.locator("nav[aria-label=Departments]").get_by_role("link", name="Files").count() == 1)
    projects = page.get_by_role("list", name="Projects")
    projects.get_by_role("button", name=re.compile("^C720")).click(); page.wait_for_timeout(250)
    check("Files: a project shows the same eight folders with counts", main.locator("ul li button", has_text="files").count() + main.locator("ul li button", has_text="1 file").count() >= 8 and "C720 Ardmullen House" in main.inner_text())
    main.get_by_role("button", name=re.compile("^Drawings")).click(); page.wait_for_timeout(250)
    check("Files: opening a folder lists its files with size, date and who added them", page.locator("tbody tr").count() >= 1 and "Added by" in page.locator("thead").inner_text() and "/ Drawings" in main.inner_text().replace("\n", " "))
    page.screenshot(path=f"{OUT}/123-files-folder.png")
    page.get_by_role("button", name="Add a file").click(); d = dlg()
    check("Files: Add a file starts in the folder you are in", d.get_by_label("Folder").input_value() == "Drawings" and d.get_by_role("button", name="Add file").is_disabled())
    d.get_by_label("Choose a file from this device").set_input_files(FIX + "notes.txt"); page.wait_for_timeout(300)
    check("Files: other kinds of file are refused with the reason", "pictures and PDFs" in d.inner_text())
    d.get_by_label("Choose a file from this device").set_input_files(FIX + "cert.pdf"); page.wait_for_timeout(400)
    d.get_by_role("button", name="Add file").click(); page.wait_for_timeout(300)
    check("Files: an added PDF appears at the top of the folder and opens", page.locator("tbody tr").first.get_by_role("button", name="cert.pdf").count() == 1)
    page.locator("tbody tr").first.get_by_role("button", name="cert.pdf").click(); page.wait_for_timeout(250)
    check("Files: the opened file offers a download", dlg().get_by_role("link", name="Download").get_attribute("download") == "cert.pdf")
    dlg().get_by_role("button", name="Close").click()
    page.get_by_label("Search all files").fill("programme"); page.wait_for_timeout(300)
    check("Files: search looks across every project and says where each file is", page.locator("tbody tr").count() >= 1 and "Where" in page.locator("thead").inner_text() and page.locator("tbody a", has_text="C7").count() >= 1, main.inner_text()[:300])
    page.get_by_label("Search all files").fill("zzzz"); page.wait_for_timeout(200)
    check("Files: a search with no match says so", "Nothing is called anything like" in main.inner_text())
    go(page, "/files/photos")
    n_ph = main.locator("ul li").count()
    page.get_by_label("Project", exact=True).select_option("C720"); page.wait_for_timeout(250)
    check("Photos: every project's photos in one grid, narrowed by project", n_ph > main.locator("ul li").count() > 0 and all(t == "C720" for t in main.locator("ul li a").all_inner_texts()))
    go(page, "/files/unsorted", "table")
    rows = page.locator("tbody tr")
    check("To be sorted: six arrivals, each with a suggestion and the reason", rows.count() == 6 and "Thiago Barbosa is on C720 this week" in main.inner_text() and "matches the work on C720" in main.inner_text() and "so the project needs choosing" in main.inner_text())
    check("To be sorted: two have a project suggested, the rest say they need one", rows.filter(has_text="Needs a project").count() == 4 and page.get_by_role("button", name="File the 2 with a project").count() == 1)
    page.screenshot(path=f"{OUT}/124-unsorted.png")
    page.get_by_role("button", name="File the 2 with a project").click(); page.wait_for_timeout(300)
    filed = data(page, "db.files.filter(f => ['Revised window schedule rev C.pdf','Photo from site, no caption.jpg'].includes(f.name)).map(f => [f.projectId, f.category]).sort()")
    check("To be sorted: filing the suggested ones puts them in the right project folders", rows.count() == 4 and filed == [["pr-C720", "Drawings"], ["pr-C720", "Photos and videos"]], filed)
    r0 = rows.filter(has_text="Scaffold handover certificate")
    check("To be sorted: File it is off until a project is chosen", r0.get_by_role("button", name="File it").is_disabled())
    r0.get_by_label("Project for Scaffold handover certificate.pdf").select_option("pr-C721"); r0.get_by_role("button", name="File it").click(); page.wait_for_timeout(300)
    check("To be sorted: choosing a project by hand files it, and the sidebar count drops", rows.count() == 3 and data(page, "db.files.find(f=>f.name==='Scaffold handover certificate.pdf').category") == "Health and safety" and "3" in page.locator("nav[aria-label$=screens]:visible").get_by_role("link", name="To be sorted").inner_text())
    # The same folders on the project's own page
    go(page, "/projects/C720?tab=files")
    check("Files tab: a project's page shows the same eight folders", main.locator("ul li button", has_text="files").count() + main.locator("ul li button", has_text="1 file").count() == 8 and main.get_by_role("tab", name=re.compile("^Files")).get_attribute("aria-selected") == "true")
    main.get_by_role("button", name=re.compile("^Drawings")).click(); page.wait_for_timeout(250)
    check("Files tab: the PDF added in the Files section is in the same folder here", main.get_by_role("button", name="cert.pdf").count() == 1 and "folder=Drawings" in page.url)
    main.get_by_role("button", name="All folders").click(); page.wait_for_timeout(200)
    check("Files tab: All folders goes back to the list of folders", main.locator("ul li button").count() == 8 and "folder=" not in page.url)
    go(page, "/projects/C720?tab=photos")
    check("Files tab: a photo filed from To be sorted shows on the project's Photos tab", "Photo from site, no caption" in main.inner_text())

    # ── Invoicing: client invoices (one list with tabs since 18 Nov, see inv_check.py for the rest)
    go(page, "/invoicing", "table")
    tabs = page.get_by_role("tablist", name="Invoices shown")
    check("Client invoices: one list, with a tab for each state", [tabs.get_by_role("tab", name=re.compile("^" + n)).count() for n in ["All", "Drafts", "Held", "Sent", "Overdue", "Paid"]] == [1] * 6 and page.locator("tbody tr").count() == data(page, "db.salesInvoices.length"))
    tabs.get_by_role("tab", name=re.compile("^Drafts")).click(); page.wait_for_timeout(250)
    check("Drafts: three ready to send, with the total and the figure before VAT", page.locator("tbody tr").count() == 3 and "before VAT" in main.inner_text() and "Total with VAT" in page.locator("thead").inner_text())
    page.locator("tbody tr", has_text="C723").get_by_role("button", name="Send", exact=True).click(); page.wait_for_timeout(300)
    dlg().get_by_role("button", name="Send invoice").click(); page.wait_for_timeout(300)
    inv = data(page, "(() => { const i = db.salesInvoices.find(i => i.status==='Invoiced' && i.issuedOn===day); return [i.accountsNo, i.dueOn > day, !!i.exportedAt] })()")
    check("Drafts: sending gives it the next accounts number and a due date", page.locator("tbody tr").count() == 2 and re.match(r"SI-104\d\d", inv[0]) and inv[1:] == [True, False], inv)
    go(page, "/invoicing/held", "table")
    check("Held: two invoices, each with the reason", page.locator("tbody tr").count() == 2 and "Snagging open" in main.inner_text() and "Extras to be agreed" in main.inner_text() and tabs.get_by_role("tab", name=re.compile("^Held")).get_attribute("aria-selected") == "true")
    page.locator("tbody tr", has_text="Snagging").get_by_role("button", name="Clear hold").click(); page.wait_for_timeout(300)
    check("Held: clearing the hold makes the invoice a draft, ready to send", page.locator("tbody tr").count() == 1 and data(page, "db.salesInvoices.filter(i=>i.status==='To invoice').length") == 3)
    go(page, "/invoicing/invoiced", "table")
    check("Unpaid: aged debt in four bands with what is owed in all", all(b in main.inner_text() for b in ["Not yet due", "1 to 30 days late", "31 to 60 days late", "Over 60 days late", "Owed to us, with VAT"]))
    page.screenshot(path=f"{OUT}/125-invoiced.png")
    late = main.locator("tbody tr", has_text="days late").first
    late.get_by_role("button", name="Mark paid").click(); page.wait_for_timeout(300)
    check("Unpaid: Mark paid asks first, and nothing is paid until it is confirmed", page.get_by_role("dialog").get_by_role("heading", name="Mark this invoice as paid?").count() == 1 and data(page, "db.salesInvoices.filter(i=>i.paidOn===day).length") == 0)
    page.get_by_role("dialog").get_by_role("button", name="Confirm paid").click(); page.wait_for_timeout(300)
    check("Unpaid: marking one paid takes it off the list", data(page, "db.salesInvoices.filter(i=>i.paidOn===day).length") == 1)
    go(page, "/invoicing/export", "table")
    waiting = data(page, "db.salesInvoices.filter(i=>i.issuedOn && !i.exportedAt).length")
    issued = data(page, "db.salesInvoices.filter(i=>i.issuedOn).length")
    book = main.get_by_label("What Sage receives, sales")
    grid = lambda: [[c.inner_text() for c in r.locator("td").all()] for r in book.locator("tbody tr").all()]
    head = lambda: [h.inner_text() for h in book.locator("thead th").all()]
    rows = grid()
    check("Export: one list of every invoice sent, row for row as Sage imports them, each marked in Sage or not yet", waiting >= 2 and f"{waiting} client invoices" in main.inner_text() and len(rows) == issued and head() == ["Type", "Account", "Nominal", "Dept", "Date", "Ref", "Details", "Net", "Tax", "VAT", "In Sage"] and all(r[0] == "SI" and r[2] == "4000" and r[8] == "T3" for r in rows) and [r[10] for r in rows].count("Not yet") == waiting, (waiting, issued, rows[:1]))
    check("Export: it is Sage only, with no choice of package", page.get_by_role("heading", name="Sage export").count() == 1 and page.get_by_role("tab", name="Xero").count() == 0 and page.get_by_role("tab", name="Spreadsheet").count() == 0 and "Sage 50" not in main.inner_text())
    page.get_by_role("tab", name=re.compile("^Not yet in Sage")).click(); page.wait_for_timeout(250)
    rows = grid()
    check("Export: the rows can be narrowed to what Sage does not have yet", len(rows) == waiting and all(r[10] == "Not yet" for r in rows))
    page.screenshot(path=f"{OUT}/126-export.png")
    with page.expect_download() as dl:
        page.get_by_role("button", name="Download CSV").click()
    body = open(dl.value.path(), encoding="utf-8", newline="").read()
    check("Export: the downloaded file is named for Sage and holds only the rows it did not have, as on screen", re.match(r"sales-invoices-sage-\d{4}-\d\d-\d\d\.csv", dl.value.suggested_filename) and body.count("\r\n") == waiting and body.startswith("SI,") and sorted(l.split(",")[5] for l in body.strip().split("\r\n")) == sorted(r[5] for r in rows), dl.value.suggested_filename)
    page.wait_for_timeout(300)
    check("Export: afterwards everything is in Sage and the button is off", "Everything is already in Sage" in main.inner_text() and page.get_by_role("button", name="Download CSV").is_disabled() and data(page, "db.salesInvoices.filter(i=>i.issuedOn && !i.exportedAt).length") == 0)
    with page.expect_download() as dl2:
        main.get_by_label("Earlier files").locator("tbody tr").first.get_by_role("button", name="Download again").click()
    check("Earlier files: the file just sent is first, and can be downloaded again", open(dl2.value.path(), encoding="utf-8", newline="").read() == body)


    # ── Invoicing: supplier invoices
    go(page, "/invoicing/supplier")
    q = page.get_by_role("list", name="Supplier invoices")
    check("Supplier invoices: every one in the queue, the ones to check first", q.get_by_role("button").count() == data(page, "db.supplierInvoices.filter(s=>(s.party??'supplier')==='supplier').length") and "To check" in q.locator("li").first.inner_text() and "4 to deal with" in main.inner_text())
    q.get_by_role("button", name=re.compile("MSM-5521")).click(); page.wait_for_timeout(300)
    paper = page.get_by_label("The invoice as received")
    check("Supplier invoice: the paper is on the left and what was read on the right", "Natural slate 500 x 250" in paper.inner_text() and "Read from the invoice" in main.inner_text() and paper.bounding_box()["x"] < main.get_by_role("heading", name="Read from the invoice").bounding_box()["x"])
    check("Supplier invoice: with no job reference it warns and will not approve", "No job reference was found" in main.inner_text() and main.get_by_role("button", name="Approve to job costs").is_disabled())
    check("Supplier invoice: slate is recognised as materials", main.get_by_label("Cost heading for: Natural slate 500 x 250, 3,000 no.").input_value() == "material")
    box = main.locator("td", has_text="Natural slate 500 x 250").first.bounding_box()
    check("Supplier invoice: the line description has room and is not squeezed into a strip", box["width"] >= 130 and box["height"] <= 90, box)
    page.screenshot(path=f"{OUT}/127-supplier-check.png")
    main.get_by_label("Project for: Natural slate 500 x 250, 3,000 no.").select_option("pr-C721"); page.wait_for_timeout(200)
    amt = main.get_by_label("Amount for: Natural slate 500 x 250, 3,000 no."); amt.click(); amt.press("ControlOrMeta+a"); page.keyboard.type("8000", delay=30); page.wait_for_timeout(250)
    check("Supplier invoice: if the lines do not add up to the subtotal it says so and stays blocked", "but the invoice subtotal is" in main.inner_text() and main.get_by_role("button", name="Approve to job costs").is_disabled())
    amt.click(); amt.press("ControlOrMeta+a"); page.keyboard.type("8850", delay=30); page.wait_for_timeout(250)
    before = data(page, "db.supplierInvoices.filter(s=>s.readStatus==='confirmed').flatMap(s=>s.allocations).filter(a=>a.projectId==='pr-C721'&&a.category==='material').reduce((s,a)=>s+a.amount,0)")
    main.get_by_role("button", name="Approve to job costs").click(); page.wait_for_timeout(300)
    check("Supplier invoice: Approve asks first, and nothing is in job costs until it is confirmed", page.get_by_role("dialog").get_by_role("heading", name="Approve this invoice?").count() == 1 and data(page, "db.supplierInvoices.find(s=>s.invoiceNo==='MSM-5521').readStatus") == "needs_review")
    page.get_by_role("dialog").get_by_role("button", name="Confirm approval").click(); page.wait_for_timeout(300)
    after = data(page, "db.supplierInvoices.filter(s=>s.readStatus==='confirmed').flatMap(s=>s.allocations).filter(a=>a.projectId==='pr-C721'&&a.category==='material').reduce((s,a)=>s+a.amount,0)")
    check("Supplier invoice: approving posts it to that project's material costs under the approver's name", round(after - before, 2) == 8850 and "Approved by Aidan King" in main.inner_text() and "3 to deal with" in main.inner_text(), (before, after, "Approved by Aidan King" in main.inner_text(), re.search(r"\d+ to deal with", main.inner_text()) and re.search(r"\d+ to deal with", main.inner_text()).group(0)))
    q.get_by_role("button", name=re.compile("BLS-20417")).click(); page.wait_for_timeout(300)
    cats = [s.input_value() for s in main.locator("select[aria-label^='Cost heading for']").all()]
    projs = [s.input_value() for s in main.locator("select[aria-label^='Project for']").all()]
    check("Supplier invoice: with a job reference every line is pre-filled, delivery as transport", projs == ["pr-C719"] * 3 and cats == ["material", "material", "transport"] and main.get_by_role("button", name="Approve to job costs").is_enabled(), (projs, cats))
    q.get_by_role("button", name=re.compile("SPH-INV-60233")).click(); page.wait_for_timeout(300)
    check("Supplier invoice: one not read yet says so on the paper", "not read yet" in paper.inner_text() and main.get_by_role("button", name="Read this invoice").count() == 1)
    main.get_by_role("button", name="Read this invoice").click(); page.wait_for_timeout(300)
    check("Supplier invoice: reading it fills in the line and suggests plant hire on C720", main.locator("select[aria-label^='Project for']").first.input_value() == "pr-C720" and main.locator("select[aria-label^='Cost heading for']").first.input_value() == "plant" and "scissor lift" in paper.inner_text(), paper.inner_text()[-200:])
    q.get_by_role("button", name=re.compile("MSM-5521")).click(); page.wait_for_timeout(300)
    main.get_by_role("button", name="Reopen").click(); page.wait_for_timeout(300)
    check("Supplier invoice: a confirmed one can be reopened, which takes it back out of job costs", data(page, "db.supplierInvoices.find(s=>s.invoiceNo==='MSM-5521').readStatus") == "needs_review" and main.get_by_role("button", name="Approve to job costs").count() == 1)
    main.get_by_role("button", name="Approve to job costs").click(); page.wait_for_timeout(300)
    page.get_by_role("dialog").get_by_role("button", name="Confirm approval").click(); page.wait_for_timeout(300)
    go(page, "/invoicing/costs", "table")
    row = page.locator("tbody tr", has_text="C721")
    mat = data(page, "Math.round(db.supplierInvoices.filter(s=>s.readStatus==='confirmed').flatMap(s=>s.allocations.map(a=>({...a, credit: s.docType==='credit_note'}))).filter(a=>a.projectId==='pr-C721'&&a.category==='material').reduce((s,a)=>s+(a.credit?-a.amount:a.amount),0))")
    check("Job costs: a line per live or finished job with a margin so far, and totals", page.locator("tbody tr").count() >= 7 and "All jobs shown" in main.inner_text() and "%" in row.inner_text() and f"{mat:,}" in row.inner_text(), (mat, row.inner_text()))
    page.screenshot(path=f"{OUT}/128-job-costs.png")

    # ── Roles
    as_role(page, "Accounts")
    check("Accounts lands on Invoicing", "/invoicing" in page.url)
    go(page, "/invoicing/supplier")
    check("Accounts check a supplier invoice, and one over the limit they send for approval instead of approving it", main.get_by_role("button", name="Send for approval").count() == 1 and main.get_by_role("button", name="Approve to job costs").count() == 0 and "so the managing director approves it" in main.inner_text())
    go(page, "/invoicing/held", "table")
    check("Accounts can see a held invoice but only open its project, not clear the hold", page.get_by_role("button", name="Clear hold").count() == 0 and page.get_by_role("link", name="Open project").count() == 1)
    as_role(page, "Site manager")
    go(page, "/invoicing")
    check("A site manager cannot open Invoicing", "/invoicing" not in page.url, page.url)
    as_role(page, "Managing director")
    go(page, "/settings/roles")
    check("Access: fifteen permissions now, with plant, invoices, answering requests and the two for approving invoices", page.locator("section", has_text="What they can do").locator("tbody tr").count() == 15 and page.get_by_role("switch", name="Accounts: Approve invoices of any size").get_attribute("aria-checked") == "false" and page.get_by_role("switch", name="Site manager: Approve subcontractor invoices for their own sites").get_attribute("aria-checked") == "true" and page.get_by_role("switch", name="Accounts: Handle invoices").get_attribute("aria-checked") == "true" and page.get_by_role("switch", name="Site manager: Manage plant and fleet").get_attribute("aria-checked") == "false")
    page.get_by_role("switch", name="Accounts: Handle invoices").click(); page.wait_for_timeout(200)
    as_role(page, "Accounts")
    go(page, "/invoicing", "table")
    check("Access: without Handle invoices, accounts can read but not draft, send or mark paid", page.get_by_role("button", name="Send", exact=True).count() == 0 and page.get_by_role("button", name="Draft an invoice").count() == 0 and page.get_by_role("button", name="Mark paid").count() == 0 and page.locator("tbody tr").count() >= 1)
    as_role(page, "Managing director")
    go(page, "/settings/roles?person=p-yard")
    check("Access: the yard manager has plant as a personal exception", "3 exceptions to the site manager level" in main.inner_text() and page.get_by_role("switch", name="Pat Scully: Manage plant and fleet").get_attribute("aria-checked") == "true")
    page.get_by_role("button", name="Sign in as Pat to check").click(); page.wait_for_timeout(500)
    go(page, "/plant", "table")
    check("Access: signed in as Pat Scully, every site's plant is listed and can be changed", main.get_by_role("link", name=re.compile("^C7")).count() >= 6 and main.get_by_role("button", name="Notify return").count() > 0)
    as_role(page, "Managing director")

    # ── Dark and phone
    page.get_by_role("button", name="Switch to dark mode").click()
    go(page, "/invoicing/supplier"); page.screenshot(path=f"{OUT}/129-supplier-dark.png")
    page.get_by_role("button", name="Switch to light mode").click()
    page.set_viewport_size({"width": 390, "height": 844})
    for path in ["/plant", "/plant/vehicles", "/files", "/files/unsorted", "/projects/C720?tab=files", "/invoicing/supplier", "/invoicing/export", "/invoicing/costs"]:
        go(page, path)
        check(f"Phone width: page itself does not scroll sideways on {path}", not page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth"))
    page.screenshot(path=f"{OUT}/130-supplier-mobile.png")

errs = []
try:
    errs = run(steps)
except Exception as ex:
    print("STOPPED EARLY:", str(ex).split("\n")[0][:400])
for name, ok, detail in results:
    print(("PASS " if ok else "FAIL ") + name + ("" if ok else f"  [{detail[:300]}]"))
print("console problems:", errs)
print(f"{sum(1 for r in results if r[1])}/{len(results)} passed")
